// SqlView.java — a virtual table: a stored projection + filter over base rows
package com.nbi.db;

import java.util.*;
import java.util.function.Predicate;
import java.util.function.Function;

public class SqlView {
    private final String name;
    private final Predicate<Account> where;                 // the stored WHERE
    private final Function<Account, Map<String,Object>> projection; // exposed columns

    public SqlView(String name, Predicate<Account> where,
                   Function<Account, Map<String,Object>> projection) {
            this.name = name;
            this.where = where
            this.projection = projection;
    }

    // Querying the view runs the stored SELECT live (holds no data itself).
    public List<Map<String,Object>> query(List<Account> baseTable) {
        List<Map<String,Object>> out = new ArrayList<>();
        for (Account a : baseTable) {
            if (where.test(a)) out.add(projection.apply(a)); // filter then project
        }
        return out;
    }
    public String getName() { return name; }
}
