// Demo.java — defines a secure, reusable view and queries it
package com.nbi.db;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        List<Account> accounts = List.of(
            new Account("1234567890","ABCPK1234A","ACTIVE","PREMIUM", 85000),
            new Account("2233445566","XYZPK9876B","CLOSED","PREMIUM", 12000),
            new Account("9988776655","LMNPK5555C","ACTIVE","STANDARD", 3000),
            new Account("5544332211","PQRPK2222D","ACTIVE","PREMIUM", 150000)
        );

        // CREATE VIEW active_premium_accounts AS
        //   SELECT mask(accountNo) AS account_masked, tier, balance
        //   FROM accounts WHERE status='ACTIVE' AND tier='PREMIUM';
        SqlView view = new SqlView(
            "active_premium_accounts",
            a -> a.status.equals("ACTIVE") && a.tier.equals("PREMIUM"), // reusable filter
            a -> {                                                      // SAFE columns only
                Map<String,Object> row = new LinkedHashMap<>();
                row.put("account_masked", "XXXXXX" + a.accountNo.substring(6)); // security
                row.put("tier", a.tier);
                row.put("balance", a.balance);
                // NOTE: pan and full accountNo are NOT exposed (security/abstraction)
                return row;
            }
        );

        System.out.println("SELECT * FROM " + view.getName() + ";");
        view.query(accounts).forEach(r -> System.out.println("  " + r));
    }
}
